alter table collect_interface_config alter column task_id drop not null;
alter table collect_protocol_config alter column task_id drop not null;
alter table device_satellite alter column task_id drop not null;
alter table telemetry_system_config alter column task_id drop not null;
alter table telemetry_parse_rule_config alter column task_id drop not null;
alter table processing_rule_config alter column task_id drop not null;
alter table calib_channel_config alter column task_id drop not null;
alter table calib_record alter column task_id drop not null;
alter table calib_record_detail alter column task_id drop not null;
alter table collect_interface_statistics alter column task_id drop not null;
alter table data_processing_statistics alter column task_id drop not null;
alter table dm_alarm_event alter column task_id drop not null;
alter table processed_telemetry_filter_selection alter column task_id drop not null;
alter table monitor_dashboard_widget alter column task_id drop not null;

alter table processing_rule_config add column if not exists scope_key varchar(32);
create unique index if not exists uk_processing_rule_scope on processing_rule_config (scope_key);
insert into processing_rule_config (scope_key, parameter_range_check_enabled)
select 'global', coalesce(max(parameter_range_check_enabled), 0) from processing_rule_config
on conflict (scope_key) do nothing;

drop index if exists uk_collect_interface_statistics_window;
create unique index uk_collect_interface_statistics_window on collect_interface_statistics (interface_id, statistics_time);
drop index if exists uk_data_processing_statistics_window;
create unique index uk_data_processing_statistics_window on data_processing_statistics (interface_id, statistics_time);
drop index if exists uk_device_satellite_task_type_code;
create unique index uk_device_satellite_task_type_code on device_satellite (type, code) WHERE is_deleted = 0;
drop index if exists uk_telemetry_system_active_path;
create unique index uk_telemetry_system_active_path on telemetry_system_config (device_satellite_id, parent_id, system_name) WHERE is_deleted = 0;
drop index if exists uk_parse_rule_task_device_index;
create unique index uk_parse_rule_task_device_index on telemetry_parse_rule_config (device_satellite_id, table_index) WHERE is_deleted = 0;
drop index if exists uk_calib_channel_task_formula;
create unique index uk_calib_channel_task_formula on calib_channel_config (calibration_formula) WHERE is_deleted = 0;
drop index if exists uk_telemetry_selection_scope;
create unique index uk_telemetry_selection_scope on processed_telemetry_filter_selection (selection_type, target_id, device_satellite_id, telemetry_code);
drop index if exists uk_monitor_widget_task_user_key;
create unique index uk_monitor_widget_task_user_key on monitor_dashboard_widget (user_id, widget_key);
